#!/usr/bin/env python3
"""
Round 184o (culprits), 5 October 2026. Needs round 183b.

Carries 183o (underwater noise, whaling logbooks) and makes the Faster map
switch plain and easy to see.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 184o (5 October)\n\nNeeds round 183b (guards on its heading). Carries round 183o, whose patch\nfailed after 183b changed the same part of test.mjs (patches/failed/\nround183o_culprits.py can be ignored). Tiles patch round184o_tiles.py beside\nit. No app.js?v= bump.\n\n- From 183o: ocean_noise (ships\' underwater noise, 2014 to 2020, three\n  pitches; Jalkanen et al. 2022, CC BY 4.0; tiles ship_noise.py) and\n  whaling_logbooks (WhalingHistory.org logbooks joined to voyages, CC BY 4.0;\n  tiles whaling_logbooks.py) under Oceans, whaling also under Marine meats.\n- The owner on the Lighter map button: hard to notice, and nobody knows what\n  it means or what changes. Now "Faster map": a filled button on its own line\n  under Reload (#lite-box), with a sentence saying every layer and basemap\n  stays and naming what it turns off (glow around points, crowd bands, 3D\n  terrain, raised heights, the Combine box, zooming out into space). While on,\n  the line is marked and the button reads "Back to the full map". Same switch\n  (localStorage culprits-lite, ?lite=1 / ?lite=0).\n- Tiles: burned_area.py reads MCD64CMQ from the University of Maryland\'s\n  fuoco SFTP server (the product\'s user guide, section 4.1, prints the login);\n  it is not in NASA\'s Earthdata catalogue, which is why the first run failed.\n  bii_nhm.py writes the museum\'s 403 refusal to bii/build.json instead of\n  failing, and reads a copy uploaded by hand to bii/download/ if there is one.\n  forest500_map.py places a country with no town in Natural Earth (the\n  British Virgin Islands) at Natural Earth\'s label point, and says so.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round184o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 183b" not in h.read_text(encoding="utf-8"):
        sys.exit("round184o: round 183b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round184o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round184o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round184o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
